    {
      "name": "ATTEMPTS_TO_REPAIR",
      "definition": "A subsequent agent action attempts to resolve a deficiency or failure identified during an earlier execution step.",
      "source_description": "An earlier observed execution deficiency or failure.",
      "target_description": "A subsequent agent action intended to resolve that deficiency or failure."
    },
    {
      "name": "USES_PREVIOUS_RESULT_AS_INPUT",
      "definition": "A subsequent agent action uses a resource, path, or value produced or identified by an earlier execution step as an input or argument.",
      "source_description": "An execution result or resource produced or identified by an earlier action.",
      "target_description": "A subsequent agent action that consumes it as an input."
    },
    {
      "name": "VERIFIES_PREVIOUS_ACTION_OUTCOME",
      "definition": "A subsequent agent action or observation step checks whether an earlier action completed successfully or produced the expected result.",
      "source_description": "An earlier action whose success or outcome requires confirmation.",
      "target_description": "A subsequent verification action or observation that checks for expected evidence."
    },
    {
      "name": "WAITS_FOR_OPERATION_COMPLETION",
      "definition": "A subsequent agent action waits for a previously initiated long-running or asynchronous operation to finish before proceeding.",
      "source_description": "An earlier action that initiated a long-running or asynchronous operation.",
      "target_description": "A subsequent action that pauses or polls until the operation completes."
    },
    {
      "name": "INSPECTS_PRODUCED_ARTIFACT_TO_DETERMINE_NEXT_ACTION",
      "definition": "A subsequent agent action examines an artifact produced by an earlier action to gather information needed to determine a later action or configuration.",
      "source_description": "An artifact or structured output produced by an earlier action.",
      "target_description": "A subsequent examination action intended to extract information for planning or configuration."
    }
  ]
}

